const upsertSyncedUser = `-- name: UpsertSyncedUser :execrows
INSERT INTO users (id, email, display_name, photo_url, workos_id, workos_created_at, workos_updated_at, workos_deleted_at, deleted_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, NULL, NULL)
ON CONFLICT (workos_id) DO UPDATE SET
  email = EXCLUDED.email,
  display_name = EXCLUDED.display_name,
  photo_url = EXCLUDED.photo_url,
  workos_id = COALESCE(users.workos_id, EXCLUDED.workos_id),
  workos_created_at = COALESCE(users.workos_created_at, EXCLUDED.workos_created_at),
  workos_updated_at = EXCLUDED.workos_updated_at,
  workos_deleted_at = NULL,
  deleted_at = NULL,
  updated_at = clock_timestamp()
WHERE users.workos_updated_at IS NULL OR EXCLUDED.workos_updated_at >= users.workos_updated_at
`

type UpsertSyncedUserParams struct {
	ID              string
	Email           string
	DisplayName     string
	PhotoUrl        pgtype.Text
	WorkosID        pgtype.Text
	WorkosCreatedAt pgtype.Timestamptz
	WorkosUpdatedAt pgtype.Timestamptz
}

func (q *Queries) UpsertSyncedUser(ctx context.Context, arg UpsertSyncedUserParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertSyncedUser,
		arg.ID,
		arg.Email,
		arg.DisplayName,
		arg.PhotoUrl,
		arg.WorkosID,
		arg.WorkosCreatedAt,
		arg.WorkosUpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertUser = `-- name: UpsertUser :one
INSERT INTO users (id, email, display_name, photo_url, admin)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (id) DO UPDATE SET
  email = EXCLUDED.email,
  display_name = EXCLUDED.display_name,
  photo_url = EXCLUDED.photo_url,
  admin = EXCLUDED.admin,
  last_login = clock_timestamp(),
  updated_at = clock_timestamp(),
  workos_deleted_at = NULL,
  deleted_at = NULL
RETURNING id, email, display_name, photo_url, admin, last_login, workos_id, workos_created_at, workos_updated_at, workos_deleted_at, deleted_at, blacklisted_at, created_at, updated_at, (xmax = 0) AS was_created
`

type UpsertUserParams struct {
	ID          string
	Email       string
	DisplayName string
	PhotoUrl    pgtype.Text
	Admin       bool
}

type UpsertUserRow struct {
	ID              string
	Email           string
	DisplayName     string
	PhotoUrl        pgtype.Text
	Admin           bool
	LastLogin       pgtype.Timestamptz
	WorkosID        pgtype.Text
	WorkosCreatedAt pgtype.Timestamptz
	WorkosUpdatedAt pgtype.Timestamptz
	WorkosDeletedAt pgtype.Timestamptz
	DeletedAt       pgtype.Timestamptz
	BlacklistedAt   pgtype.Timestamptz
	CreatedAt       pgtype.Timestamptz
	UpdatedAt       pgtype.Timestamptz
	WasCreated      bool
}

// Login and other IDP upserts mean the user is authenticating now, so clear
// WorkOS soft-delete markers left by a prior user.deleted event. Without this,
// email reuse after WorkOS deletion leaves the Speakeasy user RBAC-inactive.
func (q *Queries) UpsertUser(ctx context.Context, arg UpsertUserParams) (UpsertUserRow, error) {
	row := q.db.QueryRow(ctx, upsertUser,
		arg.ID,
		arg.Email,
		arg.DisplayName,
		arg.PhotoUrl,
		arg.Admin,
	)
	var i UpsertUserRow
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.DisplayName,
		&i.PhotoUrl,
		&i.Admin,
		&i.LastLogin,
		&i.WorkosID,
		&i.WorkosCreatedAt,
		&i.WorkosUpdatedAt,
		&i.WorkosDeletedAt,
		&i.DeletedAt,
		&i.BlacklistedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.WasCreated,
	)
	return i, err
}
